export type StandartProfileId =
  | "actuator"
  | "gps"
  | "meter"
  | "thermometer";

export type StandartKind =
  | "quantity"
  | "enum"
  | "identity"
  | "temporal"
  | "spatial"
  | "logical"
  | "media"
  | "structured"
  | "event"
  | "command";

export type StandartEncoding =
  | "bool"
  | "u8"
  | "i16"
  | "i32"
  | "f32"
  | "f64"
  | "utf8"
  | "bytes"
  | "record"
  | "enum";

export type StandartSensitivity = "public" | "internal" | "personal" | "restricted";
export type StandartStatus = "stable" | "draft" | "deprecated";

export interface LocalizedString {
  ru: string;
  en: string;
}

export interface StandartTypeCard {
  sid: StandartSid;
  path: StandartPath;
  kind: StandartKind;
  unit: string;
  encodings: StandartEncoding[];
  sensitivity: StandartSensitivity;
  status: StandartStatus;
  title: LocalizedString;
  fingerprint: string;
  aliases?: { ru?: string; short?: string; legacy?: string };
  description?: LocalizedString;
  range?: { min: number; max: number; unit?: string };
  enumValues?: string[];
}

export interface StandartProfile {
  id: StandartProfileId;
  version: string;
  title: LocalizedString;
  description?: LocalizedString;
  required: StandartSid[];
  optional: StandartSid[];
}

/** Minimum wire reading: device sends sid + value */
export interface StandartReading {
  sid: StandartSid;
  v: unknown;
  t?: number;
}

